/* 학습 해설
 * 레드블랙 상위 연결·부모 자식 또는 전체 루트 갱신
 * 같은 연결 변경을 일반 부모와 루트에서 어떻게 처리하는지 배웁니다.
 * 부모가 있으면 old가 왼쪽 자식인지 확인해 해당 자식 포인터를 new로 바꿉니다. 아니면 오른쪽 자식을 바꿉니다. 부모가 없으면 전체 root->rb_node를 바꿉니다. 일반 함수는 WRITE_ONCE를 사용하고 RCU 형태는 rcu_assign_pointer를 사용해 공개 순서를 연결합니다.
 * old가 실제 그 부모의 자식이라는 호출 전제를 지킵니다. old를 검색하거나 부모 관계가 맞는지 오류로 반환하는 함수가 아닙니다. new가 NULL인 삭제와 non-NULL인 회전·교체를 함께 추적합니다.
 */
__rb_change_child(struct rb_node *old, struct rb_node *new,
		  struct rb_node *parent, struct rb_root *root)
{
	if (parent) {
		if (parent->rb_left == old)
			WRITE_ONCE(parent->rb_left, new);
		else
			WRITE_ONCE(parent->rb_right, new);
	} else
		WRITE_ONCE(root->rb_node, new);
}

static inline void
__rb_change_child_rcu(struct rb_node *old, struct rb_node *new,
		      struct rb_node *parent, struct rb_root *root)
{
	if (parent) {
		if (parent->rb_left == old)
			rcu_assign_pointer(parent->rb_left, new);
		else
			rcu_assign_pointer(parent->rb_right, new);
	} else
		rcu_assign_pointer(root->rb_node, new);
}

