annotated:
/* 학습 해설
 * 확장 삽입·검색 경로 전파와 왼쪽 캐시
 * 삽입 위치 검색, 요약 전파, 색 복구와 최소 캐시를 하나의 흐름으로 연결하는 방법을 배웁니다.
 * less를 따라 왼쪽 또는 오른쪽 빈 자식을 찾으며 오른쪽으로 이동하면 leftmost를 거짓으로 만듭니다. rb_link_node로 연결하고 parent에서 NULL까지 propagate를 수행합니다. rb_insert_augmented_cached는 새 최소이면 rb_leftmost를 바꾸고 사용자 회전 콜백으로 색 복구를 호출합니다. 반환은 새 최소인 경우 node이고 아니면 NULL입니다.
 * 새 노드의 요약값을 먼저 준비합니다. 낮은 수준 rb_insert_augmented를 직접 사용하는 경우 삽입 검색 경로의 요약 갱신을 호출자가 수행해야 합니다. helper 주석의 suboptimal은 parent 전파 방식의 비용 설명이며 잘못된 결과라는 뜻이 아닙니다.
 */
rb_add_augmented_cached(struct rb_node *node, struct rb_root_cached *tree,
			bool (*less)(struct rb_node *, const struct rb_node *),
			const struct rb_augment_callbacks *augment)
{
	struct rb_node **link = &tree->rb_root.rb_node;
	struct rb_node *parent = NULL;
	bool leftmost = true;

	while (*link) {
		parent = *link;
		if (less(node, parent)) {
			link = &parent->rb_left;
		} else {
			link = &parent->rb_right;
			leftmost = false;
		}
	}

	rb_link_node(node, parent, link);
	augment->propagate(parent, NULL); /* suboptimal */
	rb_insert_augmented_cached(node, tree, leftmost, augment);

	return leftmost ? node : NULL;
}

