/* 학습 해설
 * FIFO 동적 할당·원소 용량 올림과 해제
 * 요청한 원소 용량을 2의 거듭제곱으로 올리고 오류와 해제를 처리하는 방법을 배웁니다.
 * __kfifo_alloc은 원소 수를 roundup_pow_of_two로 올리고 in·out을 초기화합니다. 용량 2 미만이면 -EINVAL, kmalloc_array(esize,size)가 실패하면 -ENOMEM입니다. 성공하면 mask=size-1입니다. __kfifo_free는 저장 공간을 해제하고 카운터·크기·포인터·mask를 모두 초기화합니다. 공개 alloc/free 매크로는 PTR 형태에만 이 동작을 적용합니다.
 * 예를 들어 17개 원소를 요청하면 32개 공간을 준비합니다. esize는 양수이며 타입과 맞아야 합니다. roundup의 0 입력은 정의되지 않은 조건이므로 뒤의 size<2 검사만 믿고 제로 용량을 전달하지 않습니다. 할당된 외부 저장과 사용자가 제공한 버퍼의 소유권을 구분합니다.
 */
int __kfifo_alloc(struct __kfifo *fifo, unsigned int size,
		size_t esize, gfp_t gfp_mask)
{
	/*
	 * round up to the next power of 2, since our 'let the indices
	 * wrap' technique works only in this case.
	 */
	size = roundup_pow_of_two(size);

	fifo->in = 0;
	fifo->out = 0;
	fifo->esize = esize;

	if (size < 2) {
		fifo->data = NULL;
		fifo->mask = 0;
		return -EINVAL;
	}

	fifo->data = kmalloc_array(esize, size, gfp_mask);

	if (!fifo->data) {
		fifo->mask = 0;
		return -ENOMEM;
	}
	fifo->mask = size - 1;

