/* 학습 해설
 * FIFO 사용자 복사·바이트 오류를 완전한 원소로 환산
 * 사용자 메모리 복사가 중간에 실패할 때 실제 공개 가능한 원소 수를 계산하는 방법을 배웁니다.
 * 일반 from_user·to_user는 요청 바이트를 esize로 나누어 완전한 원소만 처리합니다. 두 조각 중 첫 복사가 실패하면 실패 바이트와 아직 시도하지 않은 두 번째 조각을 합칩니다. 실패 수를 DIV_ROUND_UP으로 원소 수로 올려 부분 원소를 제외합니다. copied는 완전한 원소의 바이트 수이고 카운터는 그 원소 수만 늘립니다. 실패가 있으면 -EFAULT입니다.
 * err와 copied를 함께 확인하여 부분 성공을 처리합니다. 실패 부분의 메모리가 전혀 바뀌지 않는다는 계약은 아닙니다. 내부 __kfifo_*의 int 반환과 공개 매크로의 must_check helper 형식까지 읽어 오류 결과를 올바른 변수·비교에 연결합니다.
 */
static unsigned long kfifo_copy_from_user(struct __kfifo *fifo,
	const void __user *from, unsigned int len, unsigned int off,
	unsigned int *copied)
{
	unsigned int size = fifo->mask + 1;
	unsigned int esize = fifo->esize;
	unsigned int l;
	unsigned long ret;

	off &= fifo->mask;
	if (esize != 1) {
		off *= esize;
		size *= esize;
		len *= esize;
	}
	l = min(len, size - off);

	ret = copy_from_user(fifo->data + off, from, l);
	if (unlikely(ret))
		ret = DIV_ROUND_UP(ret + len - l, esize);
	else {
		ret = copy_from_user(fifo->data, from + l, len - l);
		if (unlikely(ret))
			ret = DIV_ROUND_UP(ret, esize);
	}
	/*
	 * make sure that the data in the fifo is up to date before
	 * incrementing the fifo->in index counter
	 */

