/* 학습 해설
 * FIFO 레코드 사용자 복사·오류 시 카운터 유지
 * 레코드 사용자 복사에서 일부 물리 복사와 전체 메시지 공개의 차이를 배웁니다.
 * from_user_r는 max_r로 요청을 길이 폭에 제한하고 헤더 포함 여유가 부족하면 copied=0으로 정상 반환합니다. 여유가 있으면 헤더와 payload를 쓰지만 복사 실패 시 copied=0,-EFAULT이고 in은 유지됩니다. to_user_r도 실패면 copied=0이고 out을 유지합니다. 출력 성공은 실제 복사가 짧아도 전체 n+recsize를 소비합니다.
 * copied=0이 공간 부족인지 오류인지 err로 구분합니다. 실패 때 큐 카운터가 유지되어도 버퍼나 사용자 목적지가 일부 바뀔 수 있습니다. 재시도·외부 부작용을 처리할 때 전혀 쓰지 않았다고 가정하지 않습니다.
 */
int __kfifo_from_user_r(struct __kfifo *fifo, const void __user *from,
	unsigned long len, unsigned int *copied, size_t recsize)
{
	unsigned long ret;

	len = __kfifo_max_r(len, recsize);

	if (len + recsize > kfifo_unused(fifo)) {
		*copied = 0;
		return 0;
	}

	__kfifo_poke_n(fifo, len, recsize);

	ret = kfifo_copy_from_user(fifo, from, len, fifo->in + recsize, copied);
	if (unlikely(ret)) {
		*copied = 0;
		return -EFAULT;
	}
	fifo->in += len + recsize;
	return 0;
}
EXPORT_SYMBOL(__kfifo_from_user_r);

int __kfifo_to_user_r(struct __kfifo *fifo, void __user *to,
	unsigned long len, unsigned int *copied, size_t recsize)

