/* 학습 해설
 * FIFO scatterlist·감긴 두 조각과 DMA 주소
 * 원형 버퍼의 비연속 구간을 장치 전송용 설명 항목으로 구성하는 방법을 배웁니다.
 * setup_sgl은 원소 위치·길이를 바이트로 바꾸고 배열 끝까지 첫 조각과 배열 처음의 두 번째 조각을 나눕니다. setup_sgl_buf는 항목 여유나 길이가 없으면 0, 있으면 sg_set_buf로 항목 한 개를 설정합니다. dma가 DMA_MAPPING_ERROR가 아니면 dma+data_offset 주소와 바이트 길이를 별도로 저장합니다. 반환은 만들어진 항목 개수입니다.
 * 실제 scatterlist 배열의 nents와 저장 공간을 제공하고 이미 매핑된 DMA 주소와 CPU 버퍼 주소를 구분합니다. 이 helper는 실제 dma_map 호출이나 장치 시작을 수행하지 않습니다. 한 항목만 제공하면 감긴 나머지를 모두 표현하지 못할 수 있습니다.
 */
static unsigned int setup_sgl(struct __kfifo *fifo, struct scatterlist *sgl,
		int nents, unsigned int len, unsigned int off, dma_addr_t dma)
{
	unsigned int size = fifo->mask + 1;
	unsigned int esize = fifo->esize;
	unsigned int len_to_end;
	unsigned int n;

	off &= fifo->mask;
	if (esize != 1) {
		off *= esize;
		size *= esize;
		len *= esize;
	}
	len_to_end = min(len, size - off);

	n = setup_sgl_buf(fifo, sgl, off, nents, len_to_end, dma);
	n += setup_sgl_buf(fifo, sgl + n, 0, nents - n, len - len_to_end, dma);

	return n;
}

