/* 학습 해설
 * FIFO DMA 일반 경로·준비와 완료의 단위
 * 장치 전송 범위를 준비하는 일과 완료한 자료를 카운터에 반영하는 일을 구분합니다.
 * 입력 prepare는 len을 여유 원소 수로, 출력 prepare는 사용 원소 수로 제한해 해당 in·out 위치의 scatterlist를 만듭니다. 카운터는 아직 바꾸지 않습니다. 공개 일반 in_finish는 완료 바이트를 원소 크기로 나눠 in에 더합니다. out_finish는 완료 바이트를 원소 수로 바꾸어 skip_count로 out을 늘립니다. finish는 별도 오류·용량 검사를 하지 않습니다.
 * prepare의 요청 원소 수, 반환 항목 수와 finish의 실제 완료 바이트 수를 각각 확인합니다. 항목 부족·부분 장치 전송이면 실제 완료 범위만 finish에 제공합니다. prepare만으로 공간이 여러 writer에게 예약되거나 DMA 동기화가 완성되는 것은 아닙니다.
 */
unsigned int __kfifo_dma_in_prepare(struct __kfifo *fifo,
		struct scatterlist *sgl, int nents, unsigned int len,
		dma_addr_t dma)
{
	unsigned int l;

	l = kfifo_unused(fifo);
	if (len > l)
		len = l;

	return setup_sgl(fifo, sgl, nents, len, fifo->in, dma);
}
EXPORT_SYMBOL(__kfifo_dma_in_prepare);

unsigned int __kfifo_dma_out_prepare(struct __kfifo *fifo,
		struct scatterlist *sgl, int nents, unsigned int len,
		dma_addr_t dma)
{
	unsigned int l;

	l = fifo->in - fifo->out;
	if (len > l)
		len = l;

	return setup_sgl(fifo, sgl, nents, len, fifo->out, dma);
}

