/* 학습 해설
 * FIFO DMA 레코드·헤더 예약 위치와 전체 소비
 * 레코드 DMA에서 payload와 길이 헤더를 서로 다른 시점에 처리하는 흐름을 배웁니다.
 * record prepare는 nents가 0이면 BUG_ON이고 len을 max_r로 제한합니다. 입력은 len+recsize가 여유 안인지, 출력은 그 값이 사용량 안인지 검사하고 헤더 뒤 위치의 scatterlist를 구성합니다. 입력 finish는 완료 len을 길이 폭으로 제한하고 헤더를 쓴 뒤 in을 len+recsize 늘립니다. 출력 finish는 header의 skip_count record 분기로 다음 레코드 전체를 소비합니다.
 * 출력 prepare는 다음 헤더 길이를 직접 읽어 요청을 자동 제한하지 않으므로 실제 record 길이에 맞는 요청을 caller가 제공해야 합니다. 출력 완료 len이 짧아도 다음 record 전체가 건너뛰어집니다. 준비·완료의 실제 장치 범위와 헤더 공간을 함께 관리합니다.
 */
void __kfifo_dma_in_finish_r(struct __kfifo *fifo,
	unsigned int len, size_t recsize)
{
	len = __kfifo_max_r(len, recsize);
	__kfifo_poke_n(fifo, len, recsize);
	fifo->in += len + recsize;
}
EXPORT_SYMBOL(__kfifo_dma_in_finish_r);

unsigned int __kfifo_dma_out_prepare_r(struct __kfifo *fifo,
	struct scatterlist *sgl, int nents, unsigned int len, size_t recsize,
	dma_addr_t dma)
{
	BUG_ON(!nents);

	len = __kfifo_max_r(len, recsize);

	if (len + recsize > fifo->in - fifo->out)
		return 0;

	return setup_sgl(fifo, sgl, nents, len, fifo->out + recsize, dma);
}
EXPORT_SYMBOL(__kfifo_dma_out_prepare_r);

