/* 학습 해설
 * 2의 거듭제곱 검사·낮은 1비트 지우기
 * 용량·정렬 단위가 정확한 2의 거듭제곱인지 비트 연산으로 확인하는 원리를 배웁니다.
 * 양수 n에서 n-1은 가장 낮은 1비트를 0으로 바꾸고 그 아래 비트를 1로 바꿉니다. 따라서 n&(n-1)은 가장 낮은 1비트를 제거합니다. 정확한 2의 거듭제곱은 1비트 하나만 있어서 결과가 0입니다. 원본은 n!=0도 함께 검사해 0을 거듭제곱으로 잘못 인정하지 않습니다.
 * FIFO 원형 mask나 특정 정렬 단위를 선택할 때 양수 unsigned long 입력을 검사합니다. 0 검사와 &&의 단락 평가를 함께 읽고 signed 음수의 의미를 그대로 가져오지 않습니다.
 */
bool is_power_of_2(unsigned long n)
{
	return (n != 0 && ((n & (n - 1)) == 0));
}

/**
 * __roundup_pow_of_two() - round up to nearest power of two
 * @n: value to round up
 */
static inline __attribute__((const))
unsigned long __roundup_pow_of_two(unsigned long n)
{
	return 1UL << fls_long(n - 1);
}

/**
 * __rounddown_pow_of_two() - round down to nearest power of two
 * @n: value to round down
 */
static inline __attribute__((const))
unsigned long __rounddown_pow_of_two(unsigned long n)
{
	return 1UL << (fls_long(n) - 1);
}

