/* 학습 해설
 * 정수 로그 fallback·최고 1비트의 위치
 * 32·64비트 양수의 정수 log2를 가장 높은 1비트로 계산하는 방법을 배웁니다.
 * __ilog2_u32는 fls(n)-1, __ilog2_u64는 fls64(n)-1입니다. fls는 가장 높은 1비트까지의 길이를 1부터 세므로 1을 빼면 0부터 시작하는 위치, 즉 floor(log2(n))입니다. CONFIG_ARCH_HAS_ILOG2_U32·U64가 있으면 이 fallback을 정의하지 않고 아키텍처 구현을 사용할 수 있습니다.
 * 기본 계산의 양수 입력 조건을 지킵니다. 헤더는 아키텍처 fallback이 n=0을 처리할 의무가 없다고 설명합니다. 어떤 호스트의 fls(0)-1 관찰을 모든 설정의 유효한 로그 계약으로 확대하지 않습니다.
 */
int __ilog2_u32(u32 n)
{
	return fls(n) - 1;
}
#endif

#ifndef CONFIG_ARCH_HAS_ILOG2_U64
static __always_inline __attribute__((const))
int __ilog2_u64(u64 n)
{
	return fls64(n) - 1;
}
#endif

